@Component("coupon-handler")
@ProcessingGroup("coupon-processing-group")
public class CouponEventHandler {
	
	// core constructor
	CouponEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCouponEvent
     */
    @EventHandler
    public void handle( CreateCouponEvent event) {
        entityManager.persist(new Coupon(event.getCouponId(), event.getCode(), event.getUsageLimit(), event.getPerCustomerLimit(), event.getExpirationDate(), event.getPromotion(), event.getRedemptions(), event.getStatus()));
    }

    /*
     * @param	event UpdateCouponEvent
     */
    @EventHandler
    public Coupon handle( UpdateCouponEvent event) {
    	entityManager.merge(new Coupon(event.getCouponId(), event.getCode(), event.getUsageLimit(), event.getPerCustomerLimit(), event.getExpirationDate(), event.getPromotion(), event.getRedemptions(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteCouponEvent
     */
    @EventHandler
    public void on( DeleteCouponEvent event) {
    	Coupon entity = new Coupon();
   
    	// ------------------------------------------
    	// apply the CouponId
    	// ------------------------------------------
    	entity.setCouponId( event.getCouponId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CouponRepository couponEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CouponEventHandler.class.getName());

}
